{
  "interpretation": {
    "name": "TightenLine3F35WithSharedNutrunner",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Bring the shared nutrunner NR7 to station st3, tighten the fasteners of variant F35 using the MES program, evaluate and record the result, then return the tool to the crib and release it.",
    "constraints": [
      "NR7 is reserved before any use and released only after it is back at the crib",
      "NR7 must be at st3 (transport-tool to station completed) before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program; no torque or tolerance literals in the Recipe",
      "The tightening must be evaluated and recorded for traceability",
      "transport-tool Steps are delegated to the Executor agvexecutor",
      "Every tool-using Step depends on reserve-tool so that the lease is renewed before physical use",
      "NR7 returns to the crib after the tightening is done"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line3-f35-nutrunner-tightening",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "MoveToStation",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-f35-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "MoveToStation",
        "next": "Tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "Tighten",
        "next": "ReturnAndRelease",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["get-f35-program", "reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": ["evaluate-tightening-f35", "record-tightening-f35"],
            "dep": ["configure-nr7", "reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate-tightening-f35",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "get-f35-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-tightening-f35",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "ReturnAndRelease",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
